n=28
g=[[0]*n for _ in range(n)]
seps=[4,9,14,19,24]
for i in seps:
    for j in range(n):
        g[i][j]=8
        g[j][i]=8
starts=[0,5,10,15,20]
fill={(0,2):3,(1,0):2,(1,1):2,(1,2):6,(1,3):2,(1,4):2,(2,0):2,(2,2):3,(3,0):2,(3,2):3,(4,2):3}
for (tr,tc),c in fill.items():
    for r in range(starts[tr],starts[tr]+4):
        for col in range(starts[tc],starts[tc]+4):
            g[r][col]=c
print(json.dumps(g))
